CREATE TABLE public.rake_records("id" uuid,"hand_id" uuid,"table_id" uuid,"club_id" uuid,"rake_amount" numeric(18,4),"bbj_contribution" numeric(18,4),"pot_size" numeric(18,4),"num_players" integer,"created_at" timestamp with time zone,"player_contributions" jsonb,"global_hand_id" bigint,"is_tournament" boolean,"tournament_id" uuid,"source" text,"metadata" jsonb,"rake_method" text,"returned_uncalled" jsonb,"terminal_closed_at" timestamp with time zone,"seat_count_in_force" integer,"max_rake_cap_in_force" numeric(18,4));
